INSERT INTO 
	COMMU_BOARD (

    SELECT
        'CMBD'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(COMMU_POST_NO), LENGTH('CMBD' ) + 1)), 0) + 1, 6, '0')
    FROM 
    	COMMU_BOARD

	  COMMU_POST_NO
	, AVATAR_ID
	, COMMU_TITLE
	, COMMU_CONTENTS
	, CATEGORY_CODE
	, COMMU_WRITE_DATE
	, COMMU_POST_HIT
	, COMMU_POST_STATUS
) VALUES (
	  #{commuPostNo}
	, #{avatarId}
	, #{commuTitle}
	, #{commuContents}
	, #{categoryCode}
	, sysdate
	, 0
	, #{commuPostStatus}
)

