UPDATE 
	COMMU_BOARD 
SET 
	  AVATAR_ID = #{avatarId}
	, COMMU_TITLE = #{commuTitle}
	, COMMU_CONTENTS = #{commuContents}
	, CATEGORY_CODE = #{categoryCode}
	, COMMU_WRITE_DATE = #{commuWriteDate}
	, COMMU_POST_HIT = #{commuPostHit}
	, COMMU_POST_STATUS = #{commuPostStatus}
	, COMMU_DELETE_DATE = #{commuDeleteDate} 
WHERE 
	COMMU_POST_NO = #{commuPostNo}
